if (!result?.ok || !result.etiqueta) {
  // Caso especial: ja separada → verificar se é na MESMA req (bloqueia) ou em outra (transfere)
  const erroLower = (result?.erro || "").toLowerCase();
  const isJaSeparada = erroLower.includes('"separada"') || erroLower.includes("separada");
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const etSep = result?.etiqueta as any;
  if (isJaSeparada) {
    // Descobre em qual requisição a etiqueta está separada (evento mais recente)
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const { data: evRaw } = await (supabase.from("etiquetas_qr_eventos") as any)
      .select("referencia_id")
      .eq("etiqueta_uid", payload.uid)
      .eq("etapa", "separacao")
      .order("created_at", { ascending: false })
      .limit(1)
      .maybeSingle();
    const refSeparada = (evRaw as { referencia_id?: string | null } | null)?.referencia_id ?? null;

    // Já separada NESTA requisição → idempotência, não conta de novo
    if (refSeparada != null && refSeparada === String(requisicaoId)) {
      playErrorSound();
      toast.error("Caixa já bipada nesta requisição");
      if (navigator.vibrate) navigator.vibrate([200, 100, 200]);
      return;
    }
    // Separada em OUTRA requisição → transfere automático pra esta
    await executarTransferencia(payload.uid, etSep?.produto_nome_snapshot || nomeEstimado, payload);
    return;
  }
  playErrorSound();
  toast.error(formatBipError(result?.erro, "separacao", result?.etiqueta));
  if (navigator.vibrate) navigator.vibrate([200, 100, 200]);
  return;
}

// Transfere separação de outra requisição para esta — chamada automaticamente
// quando o operador bipa uma etiqueta já separada em REQ DIFERENTE da atual.
// Parâmetros explícitos em vez de depender de estado (reseparirDialog removido).
const executarTransferencia = async (uid: string, produtoNome: string, payload: ScannedPayload) => {
