641	function ItemProgress({ progress }: { progress: ProgressoItem }) {
642	  const { item, caixas, totalUn, pedidoUn, pct, status } = progress;
643	  const bg = status === "completo" ? "bg-emerald-500"
644	    : status === "excesso" ? "bg-amber-500"
645	    : status === "parcial" ? "bg-[#57715B]"
646	    : "bg-zinc-300 dark:bg-zinc-700";
647	  const ring = status === "completo" ? "border-emerald-500/40 bg-emerald-500/5"
648	    : status === "excesso" ? "border-amber-500/40 bg-amber-500/5"
649	    : status === "parcial" ? "border-[#57715B]/30 bg-[#57715B]/5"
650	    : "border-border/50";
651	  return (
652	    <div className={cn("rounded-xl border-2 p-2.5", ring)}>
653	      <div className="flex items-center justify-between gap-2 mb-1.5">
654	        <p className="text-sm font-semibold leading-tight truncate flex-1 min-w-0">{item.produto_nome}</p>
655	        <div className="flex items-center gap-1.5 text-[11px] flex-shrink-0">
656	          <span className={cn(
657	            "inline-flex items-center gap-0.5 font-bold tabular-nums",
658	            status === "completo" ? "text-emerald-700" : status === "excesso" ? "text-amber-700" : "text-foreground"
659	          )}>
660	            <Boxes className="w-3 h-3" />{caixas}
661	          </span>
662	          <span className="text-muted-foreground">·</span>
663	          <span className={cn(
664	            "font-bold tabular-nums",
665	            status === "completo" ? "text-emerald-700" : status === "excesso" ? "text-amber-700" : "text-foreground"
666	          )}>
667	            {totalUn}/{pedidoUn} {(item.unidade_medida || 'un').toLowerCase()}
