669	        </div>
670	      </div>
671	      <div className="w-full h-1.5 bg-zinc-100 dark:bg-zinc-800 rounded-full overflow-hidden">
672	        <div className={cn("h-full rounded-full transition-all duration-500", bg)} style={{ width: `${pct}%` }} />
673	      </div>
674	    </div>
675	  );
676	}
